import{_ as p,o,c as e,a3 as t}from"./chunks/framework.D8u9WiMi.js";const f=JSON.parse('{"title":"AI大模型学习路线详细介绍","description":"","frontmatter":{},"headers":[],"relativePath":"resource/ai-model-study-hm.md","filePath":"resource/ai-model-study-hm.md"}'),i={name:"resource/ai-model-study-hm.md"};function a(n,r,m,l,s,h){return o(),e("div",null,[...r[0]||(r[0]=[t('<h1 id="ai大模型学习路线详细介绍" tabindex="-1"><strong>AI大模型学习路线详细介绍</strong> <a class="header-anchor" href="#ai大模型学习路线详细介绍" aria-label="Permalink to &quot;**AI大模型学习路线详细介绍**&quot;">​</a></h1><blockquote><p><strong>第一阶段：Python+AI大模型开发入门</strong></p></blockquote><p>Python是进入AI世界的通行证，而掌握AI大模型技术，则是打开智能未来大门的钥匙。在人工智能浪潮席卷全球的今天，打好Python基础将成为你在AI领域立足的根本起点，更是把握时代机遇的必备能力。学习Python与AI大模型，不仅是掌握一门技术，更是获得参与塑造未来的能力。从基础的Python语法到前沿的大模型原理，从简单的数据处理到复杂的深度学习项目，扎实的基础将让你在AI技术快速迭代的浪潮中游刃有余，在智能应用开发的实践中得心应手。</p><p><strong>课程推荐：</strong></p><p><strong>1.《一套通关Python+AI大模型》</strong>  推荐星级：⭐⭐⭐⭐⭐</p><p>本课程以大模型应用开发为主线，采用两种方式搭建垂直领域智能聊天机器人，从大模型开发Python语言、大模型部署Linux平台、大模型私有化部署框架、Python调用私有大模型API到采用LangChain+云平台快捷搭建方式，通过大模型通用应用场景，以实际解决企业实际需求为导向，培养学生大模型应用和开发能力，快速入门大模型。</p><p><a href="https://www.bilibili.com/video/BV1h1VbzHER2?cid=33131464759&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">05:20</a></p><p><a href="https://www.bilibili.com/video/BV1h1VbzHER2?cid=33131464759&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员Python+AI大模型零基础到项目实战，涵盖Python、Linux、LangChain、Ollama等，从大模型私有化部署到搭建聊天机器人一套通关 零基础入门AI大模型开发导学课程</a></p><p><a href="https://www.bilibili.com/video/BV1h1VbzHER2?cid=33131464759&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">111.4万观看3215弹幕</a></p><p><strong>2.《8天python快速入门，即学即用》</strong>  推荐星级： ⭐⭐⭐⭐⭐</p><p>本课程无缝衔接数据开发、人工智能、数据分析，后续挑战30w年薪。从零基础开始入门学习Python，开发环境使用最新版python3.10，从软件下载，IDE使用，让学生一步步了解Python，掌握Python基础语法，掌握代码编写的规范和技巧，Bug调试能力，用Python第三方库做出可视化图表。</p><p><a href="https://www.bilibili.com/video/BV1qW4y1a7fU?cid=1594645068&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">06:54</a></p><p><a href="https://www.bilibili.com/video/BV1qW4y1a7fU?cid=1594645068&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员python零基础全套教程，8天python从入门到精通，学python看这套就够了 Python导学视频</a></p><p><a href="https://www.bilibili.com/video/BV1qW4y1a7fU?cid=1594645068&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">2364.6万观看43.8万弹幕</a></p><p><strong>3.《600集Python入门到精通》</strong>  推荐星级：⭐⭐⭐⭐</p><p>本课程内容非常全面，从Linxu基础开始讲解，然后了解Python语言的起源，Python语言的设计目标，Python语言的设计哲学，Python语言的优缺点和面向对象的基本概念，以及Python语言的执行方式，还有Python集成开发环境PyCharm的使用，语法的进阶内容，全局变量，局部变量，可变数据类型和不可变数据类型以及函数返回多个值，函数的缺省参数，多值参数，递归的基本使用等，最后通过一个实战项目整合所有知识点融会贯通。</p><p><a href="https://www.bilibili.com/video/BV1ex411x7Em?cid=1596692619&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">03:51</a></p><p><a href="https://www.bilibili.com/video/BV1ex411x7Em?cid=1596692619&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员Python教程_600集Python从入门到精通教程（懂中文就能学会） 01-课程安排</a></p><p><a href="https://www.bilibili.com/video/BV1ex411x7Em?cid=1596692619&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">2071.1万观看25.9万弹幕</a></p><blockquote><p><strong>第二阶段：大模型语言进阶</strong></p></blockquote><p>当你的Python代码从“能运行”走向“够优雅”，AI大模型的世界才会向你展开更深的蓝图。Python语言进阶，不仅是学习高阶语法，更是构建能与大模型高效协作的工程能力。从面向对象到数据结构与算法，从闭包装饰器到网络编程及多任务编程，从性能优化到架构设计，扎实的Python功底是您驾驭大模型、实现创新应用的底层引擎。这不仅是技能的提升，更是从“使用者”迈向“创造者”的关键一步。</p><p><strong>课程推荐：</strong></p><p><strong>1.《AI大模型必备-Python语言进阶》</strong>  推荐星级：⭐⭐⭐⭐⭐</p><p>Python高级编程是AI开发岗位的核心要求，76%算法岗明确要求掌握面向对象、多线程及数据结构，相关技能可助转岗者面试通过率提升40%。不会Python进阶，学ML/DL必卡壳，课程从「基础语法」到「AI级代码能力」无缝过渡，无需额外补学，2周就能具备机器学习入门的代码架构能力。</p><p><a href="https://www.bilibili.com/video/BV1U2WmzfEqp?cid=33261094611&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">07:17</a></p><p><a href="https://www.bilibili.com/video/BV1U2WmzfEqp?cid=33261094611&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员大模型Python语言进阶全套视频课程，从面向对象到数据结构与算法知识精讲+项目实战一套搞定 AI大模型Python进阶课程导学</a></p><p><a href="https://www.bilibili.com/video/BV1U2WmzfEqp?cid=33261094611&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">62.3万观看2610弹幕</a></p><p><strong>2.《Python编程进阶》</strong>  推荐星级：⭐⭐⭐</p><p>本课程为Python编程进阶，能够深入学习Python高级语法，多任务编程及网络编程，掌握网络编程技术，能够实现网络通讯，知道通讯协议原理，掌握开发中的多任务编程实现方式，知道多进程多线程的原理。</p><p><a href="https://www.bilibili.com/video/BV1Ex411x7Xn?cid=464648636&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">03:24</a></p><p><a href="https://www.bilibili.com/video/BV1Ex411x7Xn?cid=464648636&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员Python高级语法进阶教程_python多任务及网络编程，从零搭建网站全套教程 01_操作系统</a></p><p><a href="https://www.bilibili.com/video/BV1Ex411x7Xn?cid=464648636&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">48.5万观看1675弹幕</a></p><blockquote><p><strong>第三阶段：Python数据分析</strong></p></blockquote><p>AI的“燃料”是数据。Pandas和NumPy是处理数据的“瑞士军刀”。告别猜测与直觉，让数据驱动决策。掌握Python数据分析，意味着能将混乱的数据转化为清晰的洞见，将繁杂的信息提炼为决策的价值。从Pandas的数据操纵到Matplotlib的可视化呈现，扎实的分析能力是您在各个领域脱颖而出的核心优势。</p><p><strong>课程推荐：</strong></p><p><strong>1.《AI大模型必备-Python数据分析》</strong>  推荐星级：⭐⭐⭐⭐⭐</p><p>本课程搭建企业级开发必备Linux开发环境，通过简洁授课方式讲解常见Linux命令。以“数据+算法+算力=模型”范式，讲解数据处理与统计分析的MySQL数据库、Numpy矩阵运算库以及Pandas数据统计分析框架，还为大家呈现了数据可视化的Matplotlib及Seaborn框架，以案例贯穿讲解，最后以一个综合案例整合所有技术栈，为机器学习和深度学习建模打下扎实基础。</p><p><a href="https://www.bilibili.com/video/BV1ReshzoEgG?cid=33306181663&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">09:45</a></p><p><a href="https://www.bilibili.com/video/BV1ReshzoEgG?cid=33306181663&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员Python数据分析全套视频教程，一套搞定Linux、MySQL、Numpy、Pandas、Matplotlib数据处理和统计分析框架 Python数据分析课程导学</a></p><p><a href="https://www.bilibili.com/video/BV1ReshzoEgG?cid=33306181663&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">49.6万观看1202弹幕</a></p><p><strong>2.《4天入门Python数据挖掘》</strong>  推荐星级：⭐⭐⭐⭐⭐</p><p>本课程该阶段主要是介绍一些数据科学领域用Python语言实现的基础库，如简洁、轻便的数据可视化展示工具Matplotlib，高效的运算工具Numpy，方便的数据处理工具Pandas，为人工智能阶段打基础。</p><p><a href="https://www.bilibili.com/video/BV1xt411v7z9?cid=67696815&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">09:19</a></p><p><a href="https://www.bilibili.com/video/BV1xt411v7z9?cid=67696815&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员Python教程，4天快速入门Python数据挖掘，系统精讲+实战案例 01-环境搭建</a></p><p><a href="https://www.bilibili.com/video/BV1xt411v7z9?cid=67696815&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">58.2万观看4267弹幕</a></p><blockquote><p><strong>第四阶段：机器学习</strong></p></blockquote><p>机器学习课程定位为AI人工智能领域的技术基础课程，旨在培养AI模型训练和模型优化技术能力；皆在解决企业实际数据挖掘问题，包括分类、回归、聚类等核心场景，通过一套课即可达到数据挖掘任务目标，更好从大量数据中挖掘出有价值的信息。</p><p><strong>课程推荐：</strong></p><p><strong>1.《AI大模型必学-机器学习宝典》</strong>  推荐星级：⭐⭐⭐⭐⭐</p><p>课程面向0基础专业学生及初学者，系统讲解机器学习基础理论、算法原理和典型应用。涵盖监督学习、无监督学习、聚类、分类等核心内容，每个算法都有配套案例，最后通过完整数据挖掘案例教学帮助学生理解机器学习在数据挖掘等领域的应用。</p><p><a href="https://www.bilibili.com/video/BV1Fzszz4Ek7?cid=33427947694&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">12:16</a></p><p><a href="https://www.bilibili.com/video/BV1Fzszz4Ek7?cid=33427947694&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员AI大模型必备《机器学习》全套视频教程，从算法到实战项目，覆盖KNN算法、线性回归、逻辑回归、决策树、集成学习、KMeans算法、数据挖掘等 机器学习课程导学</a></p><p><a href="https://www.bilibili.com/video/BV1Fzszz4Ek7?cid=33427947694&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">62.7万观看5026弹幕</a></p><p><strong>2.《3天快速入门Python机器学习》</strong>  推荐星级：⭐⭐⭐⭐</p><p>本课程是机器学习的入门课程，主要介绍一些经典的传统机器学习算法，如分类算法：KNN算法，朴素贝叶斯算法，逻辑回归，决策树算法以及随机森林；回归算法：线性回归，岭回归；聚类算法：KMeans算法，结合Python语言实现的经典机器学习库Sikit-Learn库，实现一些小型预测案例。</p><p><a href="https://www.bilibili.com/video/BV1nt411r7tj?cid=1597772240&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">16:29</a></p><p><a href="https://www.bilibili.com/video/BV1nt411r7tj?cid=1597772240&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员3天快速入门python机器学习 01-人工智能概述</a></p><p><a href="https://www.bilibili.com/video/BV1nt411r7tj?cid=1597772240&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">175.6万观看2.1万弹幕</a></p><blockquote><p><strong>第五阶段：神经网络与深度学习</strong></p></blockquote><p>深入神经网络的世界，并学会使用业界标杆框架<strong>PyTorch</strong>。这是理解、甚至未来改造大模型架构的必备技能。深度学习与神经网络不再是遥远的概念，而是能通过Python和TensorFlow/PyTorch等框架直接应用的实用技能。亲手实现卷积神经网络完成图像识别，用循环神经网络处理自然语言，通过生成式网络创造新内容。从掌握Python基础到深入理解模型原理，从在真实数据集上调优到最终部署模型，每一步都聚焦解决实际问题。掌握深度学习，意味着能将海量数据转化为智能应用。</p><p><strong>课程推荐：</strong></p><p><strong>1.《7天通关神经网络与深度学习》</strong>  推荐星级：⭐⭐⭐⭐⭐</p><p>本课程为大家呈现深度学习全貌，从深度学习发展、应用场景、Pytorch深度学习框架到ANN人工神经网络，面面俱到，课程覆盖了图像领域核心CNN算法及文本领域RNN算法，以解决实际需求为导向，案例极其丰富，通过Pytorch深度学习框架完成CNN/RNN实战任务，注重学生的实战能力培养。同时作为NLP和CV的基础课，为后续在NLP自然处理领域和CV计算机视觉领域进一步深造打下基础。</p><p><a href="https://www.bilibili.com/video/BV1c5yrBcEEX?cid=33488961547&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">14:08</a></p><p><a href="https://www.bilibili.com/video/BV1c5yrBcEEX?cid=33488961547&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员AI大模型《神经网络与深度学习》全套视频课程，涵盖Pytorch深度学习框架、BP神经网络、CNN图像分类算法及RNN文本生成算法 深度学习与神经网络课程导学</a></p><p><a href="https://www.bilibili.com/video/BV1c5yrBcEEX?cid=33488961547&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">78.9万观看4300弹幕</a></p><p><strong>2.《3天玩转Python深度学习》</strong>  推荐星级：⭐⭐⭐⭐</p><p>本阶段是深度学习的入门课程，主要介绍经典的深度学习框架TensorFlow的使用，IO操作，以及神经网络基础、卷积神经网络的相关知识，并用卷积神经网络原理搭建、设计自己的网络，实现对验证码图片内容的识别。</p><p><a href="https://www.bilibili.com/video/BV1Wt411C75s?cid=68618794&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">09:56</a></p><p><a href="https://www.bilibili.com/video/BV1Wt411C75s?cid=68618794&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员3天带你玩转Python深度学习TensorFlow框架 01-上节回顾</a></p><p><a href="https://www.bilibili.com/video/BV1Wt411C75s?cid=68618794&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">46万观看3803弹幕</a></p><blockquote><p><strong>第六阶段：NLP自然语言处理</strong></p></blockquote><p>自然语言处理（NLP）远不止是调用API，它是让机器真正理解人类语言、实现智能交互的核心技术。通过Python与预训练模型，你将亲手完成文本分类、情感分析、智能问答和机器翻译等核心任务。从掌握分词、词向量等基础概念，到熟练运用Transformer、BERT等现代架构，再到数据清洗、模型微调与服务部署——系统学习NLP，意味着你能将海量文本转化为真正的商业价值与创新应用。</p><p><strong>课程推荐：</strong></p><p><strong>1.《NLP从入门到精通》</strong>  推荐星级：⭐⭐⭐⭐⭐</p><p>本课程基于神经网络与Pytorch框架，聚焦NLP核心技术与Transformer体系，面向有基础的学习者。以“原理拆解+代码实操”为核心，将复杂的Transformer架构（输入嵌入、位置编码、多头注意力、编码器/解码器）通过“公式解读+步骤拆解+可视化分析”讲透，并且覆盖文本分类、机器翻译、情感分析等经典任务案例。</p><p><a href="https://www.bilibili.com/video/BV1GByoBfE73?cid=33628553234&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">14:21</a></p><p><a href="https://www.bilibili.com/video/BV1GByoBfE73?cid=33628553234&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员AI大模型NLP自然语言处理全套视频教程，从传统序列模型到基于Transformer的预训练模型，构建完整NLP知识体系与项目实战 NLP自然语言处理课程导学</a></p><p><a href="https://www.bilibili.com/video/BV1GByoBfE73?cid=33628553234&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">29.9万观看1549弹幕</a></p><p><strong>2.《20个小时玩转NLP自然语言处理》</strong>  推荐星级：⭐⭐⭐⭐</p><p>本课程由浅到深，由原理到实践，层层递进的讲解方式，适合自然语言处理入门学习。在解析理论算法的同时，更加注重代码实践。每一个知识点，每一个专题都以代码驱动, 结合实际案例模型, 培养真实代码开发能力和解决实际问题的能力。</p><p><a href="https://www.bilibili.com/video/BV17y4y1m737?cid=284472926&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">03:27</a></p><p><a href="https://www.bilibili.com/video/BV17y4y1m737?cid=284472926&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">Python人工智能20个小时玩转NLP自然语言处理【黑马程序员】 1.1认识Pytorch-第1步-什么是Pytorch</a></p><p><a href="https://www.bilibili.com/video/BV17y4y1m737?cid=284472926&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">52.1万观看3167弹幕</a></p><blockquote><p><strong>第七阶段：Coze智能体开发</strong></p></blockquote><p>在大模型时代，真正的竞争力不是“会不会用AI”，而是“能不能让AI为你工作”。</p><p>Coze 平台作为字节跳动推出的低门槛AI Agent开发引擎，正成为普通人构建个性化智能体的最佳入口——无需代码、完全免费、功能强大，却能实现从内容生成、知识问答到任务自动化的完整闭环。</p><p>该阶段课程不是简单的功能教学，而是一套AI大模型产品化思维训练营。你将系统掌握提示词工程、知识增强（RAG）、插件调用、工作流编排、记忆系统设计与多端发布等核心能力，不仅能复现课程中的爆款Bot，更能举一反三，独立设计出解决真实问题的AI产品——无论是职场提效工具、自媒体内容引擎，还是垂直领域智能客服，你都能快速落地。</p><p><strong>课程推荐：</strong></p><p><strong>《从0到1玩转Coze：AI Agent开发实战全攻略》</strong> 推荐星级：⭐⭐⭐⭐⭐</p><p>这是一门专为B站初学者打造的高实操、快上手、强落地的Coze智能体平台入门课！课程以“案例驱动+避坑指南+模板复用”为核心，涵盖10+爆款Bot拆解、2个完整工作流项目（课程答疑助手 &amp; 历史人物视频脚本生成器）、微信公众号接入、Coze商店上架等真实场景。学完本课，你不仅能做出高情商沟通助手、游戏攻略专家、热点追踪Bot等实用工具，还能掌握提示词黄金公式、知识库优化技巧、多插件协作逻辑与数据持久化方法——真正把AI变成你的超级外挂！</p><p><a href="https://www.bilibili.com/video/BV12omoB4ExF?cid=34721042168&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">07:48</a></p><p><a href="https://www.bilibili.com/video/BV12omoB4ExF?cid=34721042168&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员全网最全Coze智能体入门到项目实战全套教程，从AI Agent开发入门到6大AI智能体实战项目，涵盖提示词Prompt、RAG、Bot发布微信公众号 Coze智能体导学课程</a></p><p><a href="https://www.bilibili.com/video/BV12omoB4ExF?cid=34721042168&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">48.8万观看1153弹幕</a></p><blockquote><p><strong>第八阶段：大模型应用基础</strong></p></blockquote><p>你以为大模型应用只是输入提示词等结果？不——它是基于预训练大模型（LLM），通过系统方法构建高可用AI解决方案！本阶段课程带你跨越简单问答，系统掌握大模型应用开发全流程：从Hugging Face工具链操作、提示工程优化、LangChain核心框架、RAG实战案例、ReAct框架到垂直领域智能客服构建。无需深厚基础，通过真实项目实战，你就能独立完成智能客服、内容生成等AI应用开发，成为企业急需的&quot;既懂原理又能落地&quot;的复合型人才！</p><p><strong>课程推荐：</strong></p><p><strong>《大模型RAG与Agent智能体项目实战》</strong> 推荐星级：⭐⭐⭐⭐⭐</p><p>本课程基于主流的LangChain技术，完成企业级项目实战案例，注重学生的实战能力培养。讲解方式深入浅出，幽默风趣，既能做到清晰易懂，又能做到讲解深度的兼顾。</p><p><a href="https://www.bilibili.com/video/BV1yjz5BLEoY?cid=35522677539&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">05:18</a></p><p><a href="https://www.bilibili.com/video/BV1yjz5BLEoY?cid=35522677539&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员大模型RAG与Agent智能体项目实战教程，基于主流的LangChain技术从大模型提示词到实战项目</a></p><p><a href="https://www.bilibili.com/video/BV1yjz5BLEoY?cid=35522677539&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">90万观看2919弹幕</a></p><blockquote><p><strong>第九阶段：大模型微调</strong></p></blockquote><p>零基础玩转大模型！从Transformer原理到实战微调，手把手教你用LoRA/PEFT技术将通用AI改造成懂你业务的专属助手。无需高深数学，用普通显卡就能实现从模型原理理解到行业落地的全流程，轻松完成客服问答、内容生成等实战任务，助你快速成为企业急需的AI实战型人才！</p><p><strong>课程推荐</strong>：</p><p>黑马程序员将推出以下课程，敬请期待~！</p><p><strong>《AI大模型微调基础到实战》</strong></p><p>一课覆盖从PyTorch入门到Transformer实战，手把手带你搭建神经网络、解密LLM背后的注意力机制，实现机器翻译。无需高深数学，通过房价预测、手机价格预测、情感分析等趣味案例，轻松掌握BERT、GPT、Deepseek等主流模型原理，并通过PEFT微调技术低成本定制大模型。课程涵盖LoRA等前沿方法，带你在消费级显卡上实现模型个性化训练！最后用LLaMA-Factory亲手微调专属问答机器人。带你从&quot;调包侠&quot;蜕变成为懂原理、能实战的AI工程师。</p><br><blockquote><p><strong>第十阶段：多模态</strong></p></blockquote><p>你以为多模态只是简单处理图片和文字？不——它是融合文本、图像、音频、视频的下一代AI核心技术！在这阶段课程中，你将亲手打造令人惊叹的多模态应用。从Stable Diffusion文生图、Sora视频生成等核心技术，到腾讯混元、阿里通义万象等国内热门产品。无需基础，手把手教学，让你轻松实现从图文对接到视频创作的完整流程，快速具备图像生成、短视频制作等实战能力，成为多模态领域的抢手人才！</p><p><strong>课程推荐：</strong></p><p><strong>1.《从零玩转Stable Diffusion与腾讯混元生图》</strong> 推荐星级：⭐⭐⭐⭐⭐</p><p>该课程专为零基础小白设计的AI文生图入门课！你不需要会画画或懂代码，就能轻松玩转最火的AI绘画工具。我们将手把手教你用“Stable Diffusion”模型微调生成各种炫酷图片，并用“腾讯混元”快速搞定中文场景的AI绘画。还将解锁小程序开发实战，教你如何将AI绘画能力嵌入自己的应用中，打造个性化创作工具。 从工具使用、模型训练到商业实战，全程干货，让你快速从新手变高手，用AI释放你的创造力！</p><p><a href="https://www.bilibili.com/video/BV1sMk6BtE3f?cid=33912587323&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">11:01</a></p><p><a href="https://www.bilibili.com/video/BV1sMk6BtE3f?cid=33912587323&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">黑马程序员多模态AIGC图像生成_大模型开发全套视频教程，零基础玩转Stable Diffusion+腾讯混元生图实现企业级AI绘画小程序实战项目 多模态AIGC图像生成课程导学</a></p><p><a href="https://www.bilibili.com/video/BV1sMk6BtE3f?cid=33912587323&amp;p=1&amp;spm_id_from=333.1369.0.0" target="_blank" rel="noreferrer">6.9万观看105弹幕</a></p><br><p>时代风起云涌，技术日新月异。AI行业的每一次突破，都在告诉我们：<strong>选对赛道和努力一样重要。</strong></p><p>在黑马，已经有无数学长学姐实现了职业逆袭！在这里不仅有前沿的课程、大厂级的实战项目、用心的老师，更有无数和你一样怀揣梦想、敢于行动的同行者。</p><p><strong>看清趋势，掌握未来！你的高起点职业生涯，从黑马开始。</strong></p>',121)])])}const d=p(i,[["render",a]]);export{f as __pageData,d as default};
